descriptor.controllerScript:
self.onInit = function() {
    var html5QrCode;

    self.ctx.$scope.scanQR = function() {
        var selectedCourse = document.getElementById('courseSelect').value;

        document.getElementById('scanBtn').style.display = 'none';
        document.getElementById('reader').style.display = 'block';
        document.getElementById('status').innerText = "Starting camera...";
        document.getElementById('status').style.color = 'blue';

        try {
            // Use the lower-level API to instantly start the back camera without extra UI menus!
            html5QrCode = new Html5Qrcode("reader");

            html5QrCode.start(
                { facingMode: "environment" }, // Force the back camera
                {
                    fps: 10,
                    qrbox: { width: 250, height: 250 }
                },
                function onScanSuccess(scannedToken, decodedResult) {
                    // Stop the camera instantly on success
                    html5QrCode.stop().then(function() {
                        document.getElementById('reader').style.display = 'none';
                        document.getElementById('scanBtn').style.display = 'block';
                        sendAttendance(scannedToken, selectedCourse);
                    });
                },
                function onScanFailure(error) {
                    // Ignore continuous scanning errors
                }
            ).catch(function(err) {
                document.getElementById('status').innerText = "Camera access denied or not found.";
                document.getElementById('status').style.color = 'red';
                document.getElementById('scanBtn').style.display = 'block';
                document.getElementById('reader').style.display = 'none';
            });
        } catch(e) {
            document.getElementById('status').innerText = "Failed to load camera library.";
            document.getElementById('status').style.color = 'red';
        }
    };

    document.getElementById('scanBtn').onclick = self.ctx.$scope.scanQR;

    function sendAttendance(token, course) {
        document.getElementById('status').innerText = "Sending...";
        document.getElementById('status').style.color = '#f39c12';

        var telemetry = {
            qr_token: token,
            course: course,
            user_email: self.ctx.currentUser.email
        };

        // We use native fetch to talk directly to the Terminal, injecting the logged-in user's email!
        fetch('https://eu.thingsboard.cloud/api/v1/KQYXoDYomNDMJ29qdH0k/telemetry', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(telemetry)
        }).then(response => {
            if (response.ok || response.type === 'opaque') {
                document.getElementById('status').innerText = "✅ Attendance Logged for " + course + "!";
                document.getElementById('status').style.color = '#27ae60';
            } else {
                throw new Error('Network response was not ok');
            }
        }).catch(error => {
            document.getElementById('status').innerText = "❌ Network Error.";
            document.getElementById('status').style.color = 'red';
        });
    }
};
